#[test]
fn schema_two_campaign_plan_stays_readable_without_runtime_identity() {
    let plan = frozen(&["model-a"], &["read_question_v1"]);
    let mut json = serde_json::to_value(&plan).expect("campaign JSON");
    json["schema_version"] = serde_json::Value::from(2_u32);
    if let Some(object) = json.as_object_mut() {
        object.remove("benchmark_runtime");
    }
    let legacy: CampaignPlan = serde_json::from_value(json).expect("schema two plan");
    assert_eq!(legacy.schema_version, 2);
    assert_eq!(legacy.benchmark_runtime(), None);
    assert_eq!(legacy.plan_digest(), plan.plan_digest());
}

